    const row = Math.floor(tile / ATLAS_COLUMNS);
    const rows = ATLAS_ROWS;
    const pad = 0.0008;
    const u0 = col / ATLAS_COLUMNS + pad;
    const v0 = row / rows + pad;
    const u1 = (col + 1) / ATLAS_COLUMNS - pad;
    const v1 = (row + 1) / rows - pad;
    return [u0, v0, u1, v1];
  };

